import {open} from './login.mjs';
const {b,p}=await open();
const plan = {reject:['RF-3827','RF-5259','RF-95911','RF-30714'], approve:['RF-2420','RF-31418','RF-44221','RF-50523']};
for (const [act, ids] of Object.entries(plan)) for (const id of ids) {
  let found=false;
  for (const pg of [1,2,3]) {
    await p.goto('http://127.0.0.1:54569/refunds?page='+pg);
    await p.waitForLoadState('networkidle');
    const tr = p.locator(`tr[data-id="${id}"]`);
    if (await tr.count()) {
      const cls = act==='approve'?'.ap':'.rj';
      await tr.locator(cls).click();
      await p.waitForTimeout(700);
      console.log(id, act, '->', (await tr.locator('.st').textContent()).trim());
      found=true; break;
    }
  }
  if(!found) console.log(id,'NOT FOUND');
}
for (const pg of [1,2,3]) {
  await p.goto('http://127.0.0.1:54569/refunds?page='+pg);
  await p.waitForLoadState('networkidle');
  const rows = await p.$$eval('tbody tr', trs=>trs.map(tr=>[...tr.querySelectorAll('td')].map(t=>t.textContent.trim()).join(' | ')));
  console.log('PAGE',pg); rows.forEach(r=>console.log(r));
}
await b.close();
EOF
